import {workPromotions,colombiaDay} from './assignments.js';
import {buildReport,reportTypes,reportExport} from './report-engine.js';
import {workbook} from './report-xlsx.js';
import {unitPrice} from './pricing.js';
import {favorites,toggleFavorite} from './favorites.js';
import {stages,transitions,summarize} from './commercial.js';
import {read,write,remove} from './storage.js';

const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(v||0);
const date=v=>v?new Date(v.length===10?v+'T12:00:00':v).toLocaleDateString('es-CO',{day:'numeric',month:'short',year:'numeric'}):'—';
const datetime=v=>v?new Date(v).toLocaleString('es-CO'):'—';
const localDate=colombiaDay;
const paths={home:'M3 10l9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',stores:'M3 10h18M4 10v11h16V10M2 10l3-7h14l3 7M9 21v-7h6v7',catalog:'M4 3h7v8H4zM15 3h5v8h-5zM4 15h7v6H4zM15 15h5v6h-5z',orders:'M6 3h12v18H6zM9 7h6M9 11h6M9 15h4',promotions:'M3 4h9l9 9-8 8-10-10zM7 8h.01',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M17 4a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-4',sync:'M20 7a9 9 0 0 0-15-2L2 8m0-6v6h6M4 17a9 9 0 0 0 15 2l3-3m0 6v-6h-6',audit:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 12l3 3 5-6',arrow:'M5 12h14m-5-5 5 5-5 5',plus:'M12 5v14M5 12h14',search:'M21 21l-6-6M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14',check:'M5 12l4 4L19 6',wifi:'M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0M8 16a6 6 0 0 1 8 0M12 20h.01',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0zM12 13a3 3 0 1 0 0-6 3 3 0 0 0 0 6',box:'M3 7l9-5 9 5v10l-9 5-9-5zM3 7l9 5 9-5M12 12v10M7 4l10 6',logout:'M9 3H4v18h5M10 12h12m-4-4 4 4-4 4',close:'M6 6l12 12M6 18 18 6',menu:'M3 6h18M3 12h18M3 18h18',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',clock:'M12 8v5l3 2M22 12a10 10 0 1 0-20 0 10 10 0 0 0 20 0',edit:'M4 16L16 4l4 4L8 20H4zM14 6l4 4',alert:'M12 3L2 21h20zM12 9v5M12 17h.01',profile:'M20 21a8 8 0 0 0-16 0M12 13a5 5 0 1 0 0-10 5 5 0 0 0 0 10'};
const icon=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.box}"/></svg>`;
const roles={admin:'Administrador',ventas:'Ventas y Marketing',agente:'Agente comercial',tic:'Operaciones TIC'};
const titles={suppliers:'Proveedores',inventory:'Inventario',returns:'Devoluciones',reports:'Reportes',home:'Resumen',stores:'Tiendas',catalog:'Catálogo de productos',orders:'Pedidos',promotions:'Promociones',users:'Equipo y usuarios',sync:'Centro de sincronización',audit:'Auditoría',profile:'Mi perfil'};
const state={reportSection:null,reportFilters:{type:'general',sort:'name'},data:null,queue:[],draft:null,page:'home',search:'',promotion:'',category:'',orderStatus:'',commercial:'',reportFrom:'',reportTo:'',reportPromo:'',reportAgent:'',favoritesOnly:false,newOrders:[],orderStore:'',orderPromo:'',from:'',to:'',offline:!navigator.onLine,syncing:false,audits:[]};
let toastTimer;
const loginLocks=new Map();
function updateLoginLock(){const form=$('#login-form');if(!form)return;const until=loginLocks.get(form.elements.email.value.trim().toLowerCase())||0,remaining=Math.ceil((until-Date.now())/1000),button=form.querySelector('[type=submit]');if(remaining>0){button.disabled=true;button.dataset.locked='1';form.querySelector('.form-error').textContent=`Acceso bloqueado. Podrás reintentar en ${remaining} segundos.`;}else if(button.dataset.locked){button.disabled=false;delete button.dataset.locked;form.querySelector('.form-error').textContent='Ya puedes volver a intentar iniciar sesión.';}}
setInterval(updateLoginLock,1000);
document.addEventListener('input',e=>{if(e.target.closest('#login-form'))updateLoginLock();});
function toast(message,error=false){$('#toast').textContent=message;$('#toast').className='show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').className='',6000);}
function requireConnection(){state.offline=true;}
function connectionReady(){state.offline=false;document.querySelector('#connection-required')?.close();}
async function api(path,method='GET',body){if(!navigator.onLine){requireConnection();throw Object.assign(new Error('Conexión requerida para continuar.'),{network:true});}let response;try{response=await fetch('/api'+path,{method,headers:{'Content-Type':'application/json','X-PharmaBoost':'1'},body:body===undefined?undefined:JSON.stringify(body),signal:AbortSignal.timeout(15000)});}catch(e){requireConnection();throw Object.assign(new Error('No se pudo conectar con el servidor. Puedes reintentar.'),{network:true});}const result=await response.json();if(!response.ok)throw Object.assign(new Error(result.error||'No se pudo completar la operación.'),{status:response.status,details:result.details});return result;}
const uid=()=>state.data.user.id;
const isAgent=()=>state.data.user.role==='agente';
const manage=()=>['admin','ventas'].includes(state.data.user.role);
const active=p=>p.status==='activa'&&p.start_date<=localDate()&&p.end_date>=localDate();
const availablePromos=()=>workPromotions(state.data.promotions,state.data.user);
const activePromos=()=>availablePromos().filter(active);
const currentPromo=()=>availablePromos().find(p=>String(p.id)===String(state.promotion))||activePromos()[0]||availablePromos()[0];
const initials=name=>name.split(' ').slice(0,2).map(n=>n[0]).join('');
const badge=(status,label)=>`<span class="badge ${esc(status)}">${esc(label||({enviado:'Enviado',revision:'En revisión',pendiente:'Por sincronizar',error:'Con error',borrador:'Borrador',activa:'Activa',finalizada:'Finalizada',exito:'Correcto',aviso:'Aviso'}[status]||status))}</span>`;
const empty=(title,detail='',symbol='box')=>`<div class="empty">${icon(symbol,36)}<h3>${esc(title)}</h3><p>${esc(detail)}</p></div>`;
const option=(id,label,current)=>`<option value="${esc(id)}" ${String(id)===String(current)?'selected':''}>${esc(label)}</option>`;
function promoSelect(){return `<select id="promotion-filter" aria-label="Promoción de trabajo">${availablePromos().map(p=>option(p.id,p.name,currentPromo()?.id)).join('')}</select>`;}
function modal(content){$('#modal').innerHTML=`<button type="button" class="icon-button modal-close" data-action="close" aria-label="Cerrar">${icon('close')}</button>${content}`;const title=$('#modal h2');if(title){title.id='modal-title';$('#modal').setAttribute('aria-labelledby','modal-title');}$('#modal').showModal();}
function closeModal(){$('#modal').close();}
function busy(button,value){if(button){button.disabled=value;button.classList.toggle('busy',value);}}

function renderLogin(error=''){
  $('#app').innerHTML=`<main class="login auth-switch"><section class="login-story"><a class="brand" href="/"><span class="brand-symbol">+</span>PharmaBoost<span class="brand-dot">®</span></a><div><p class="eyebrow">DEUTSCHE PHARMA</p><h1>Más cerca de<br>cada tienda.</h1><p>Todo lo que necesitas para llevar tus promociones del catálogo al punto de venta.</p><div class="login-points"><span>${icon('stores')} Tus tiendas, en un solo lugar</span><span>${icon('catalog')} La subgama de cada promoción</span><span>${icon('sync')} Seguimiento de tus pedidos y visitas</span></div></div><small>Promociones de ventas · Plataforma comercial</small></section><section class="login-form"><div class="login-card auth-login"><span class="eyebrow green">TU ESPACIO DE TRABAJO</span><h2>Bienvenido de nuevo</h2><p class="muted">Ingresa con la cuenta asignada por tu administrador.</p><form id="login-form"><label>Correo electrónico<input name="email" type="email" autocomplete="username" placeholder="tu.correo@empresa.com" required></label><label>Contraseña<input name="password" type="password" autocomplete="current-password" placeholder="Tu contraseña" required></label><p class="form-error" role="alert">${esc(error)}</p><button class="button primary full" type="submit">Iniciar sesión ${icon('arrow')}</button></form><a class="button secondary full register-link" href="/catalogo.html">Ver productos sin cuenta</a><button class="button secondary full register-link" data-action="register">Crear cuenta</button><p class="login-footnote">Inicia sesión con conexión para preparar tus datos. Después podrás registrar pedidos y visitas sin señal.</p></div><div class="login-card auth-register" hidden inert><span class="eyebrow green">SOLICITUD DE ACCESO</span><h2>Crear cuenta</h2><p class="muted">Completa tus datos. El administrador revisará la solicitud y asignará tu rol.</p><form id="register-form"><label>Nombre completo<input name="name" required minlength="2" maxlength="120"></label><label>Correo electrónico<input name="email" type="email" required></label><label>Contraseña<input name="password" type="password" minlength="10" required autocomplete="new-password"></label><p class="note">No puedes elegir el rol. Por seguridad, el administrador lo asignará después de revisar tu solicitud.</p><p class="form-error" role="alert"></p><div class="modal-actions"><button type="button" class="button secondary" data-action="auth-login">Volver al inicio</button><button class="button primary" type="submit">Enviar solicitud</button></div></form></div></section></main>`;
}

function setAuthMode(register){const root=$('.auth-switch');if(!root)return;const login=$('.auth-login'),signup=$('.auth-register');root.classList.toggle('is-register',register);login.hidden=register;login.inert=register;signup.hidden=!register;signup.inert=!register;const story=$('.login-story');story.querySelector('h1').innerHTML=register?'Tu próximo paso<br>empieza aquí.':'Más cerca de<br>cada tienda.';story.querySelector('div>p:not(.eyebrow)').textContent=register?'Solicita tu acceso al equipo comercial. Tu administrador revisará la cuenta y asignará tu rol.':'Todo lo que necesitas para llevar tus promociones del catálogo al punto de venta.';(register?signup:login).querySelector('h2').setAttribute('tabindex','-1');(register?signup:login).querySelector('h2').focus({preventScroll:true});}
function showRegister(){setAuthMode(true);}

function nav(){let items=['home','stores','catalog','orders','promotions'];if(manage())items.push('suppliers','inventory','returns','reports');if(state.data.user.role==='admin')items.push('users');items.push('sync');if(['admin','tic'].includes(state.data.user.role))items.push('audit');return items.map(key=>`<a href="#${key}" class="nav-link ${state.page===key?'active':''}">${icon(key)}<span>${titles[key].replace('Catálogo de productos','Catálogo').replace('Centro de sincronización','Sincronización')}</span>${key==='orders'&&state.queue.length?`<span class="nav-count">${state.queue.length}</span>`:''}</a>`).join('');}
function render(){
  if(!state.data)return renderLogin();
  const user=state.data.user;
  if(state.page==='users'&&user.role!=='admin'||state.page==='audit'&&!['admin','tic'].includes(user.role))state.page='home';
  $('#app').innerHTML=`<div class="layout"><aside class="sidebar"><a href="#home" class="brand"><span class="brand-symbol">+</span>PharmaBoost<span class="brand-dot">®</span></a><div class="workspace-label">DEUTSCHE PHARMA <span>DP</span></div><div class="nav-caption">ESPACIO DE TRABAJO</div><nav aria-label="Menú principal">${nav()}</nav><div class="sidebar-bottom"><button class="user-control" data-action="profile"><span class="avatar">${esc(initials(user.name))}</span><span><strong>${esc(user.name)}</strong><small>${roles[user.role]}</small></span>${icon('profile',17)}</button><button class="logout" data-action="logout">${icon('logout',17)} Cerrar sesión</button></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-menu" data-action="menu" aria-label="Abrir navegación">${icon('menu')}</button><span>Mi espacio</span><span>/</span><strong>${titles[state.page]}</strong></div><div class="header-tools">${manage()?`<button class="button secondary notification-button" data-action="notifications" aria-label="Avisos de pedidos">Avisos <span id="notification-count">${state.newOrders.length}</span></button>`:''}<button data-action="sync-now" class="connection ${state.offline?'offline':''}" aria-label="Sincronizar datos">${icon(state.offline?'clock':'wifi',17)}<span>${state.syncing?'Sincronizando…':state.offline?'Sin conexión':'En línea'}</span></button></div><div class="topbar-right account-header"><span class="header-date"></span><span data-theme-slot></span><button data-action="profile" class="account-link" aria-label="Mi cuenta">${icon('users',21)}<span class="account-label">Mi cuenta</span><span class="avatar account-avatar">${esc(initials(user.name))}</span></button></div></header><main id="content">${pageContent()}</main><footer class="app-footer"><span>PharmaBoost <span class="muted">/</span> Deutsche Pharma</span><span>Última actualización: ${datetime(state.data.synced_at)}</span></footer></div></div>`;
  bindImages();
}

function pageHeader(title,subtitle,actions=''){return `<div class="page-heading"><div><p class="eyebrow green">GESTIÓN COMERCIAL</p><h1>${title}</h1><p class="muted">${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`;}
function stat(label,value,detail,symbol){return `<article class="stat-card"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon(symbol)}</span></div><strong class="stat-value">${value}</strong><span class="stat-detail">${detail}</span></article>`;}
function visited(sid,pid){return state.data.orders.some(o=>o.store_id===sid&&o.promotion_id===pid)||state.data.visits.some(v=>v.store_id===sid&&v.promotion_id===pid)||state.queue.some(q=>q.payload.store_id===sid&&q.payload.promotion_id===pid);}
function pageContent(){return ({suppliers:suppliersPage,inventory:inventoryPage,returns:returnsPage,reports:reportsPage,home:homePage,stores:storesPage,catalog:catalogPage,orders:ordersPage,promotions:promotionsPage,users:usersPage,sync:syncPage,audit:auditPage,profile:profilePage}[state.page]||homePage)();}
function homePage(){
  const {orders,stores,products}=state.data;const promo=currentPromo();const assigned=promo?stores.filter(s=>promo.store_ids.includes(s.id)):[];const done=assigned.filter(s=>visited(s.id,promo.id)).length;
  const total=orders.reduce((s,o)=>s+o.total,0);
  const action=isAgent()?`<button class="button primary" data-action="new-order">${icon('plus')} Nuevo pedido</button>`:manage()?`<button class="button primary" data-action="new-promotion">${icon('plus')} Nueva promoción</button>`:'';
  return pageHeader(`Hola, ${esc(state.data.user.name.split(' ')[0])} <span class="greeting-mark">✳</span>`,'Así van tus promociones. Cada visita cuenta.',action)+
  `<div class="stats-grid">${stat('Pedidos recibidos',orders.length,'Disponibles para Ventas y Marketing','orders')}${stat('Valor de los pedidos',money(total),'Total registrado · COP','promotions')}${stat('Tiendas visitadas',`${done}<span class="stat-denominator"> / ${assigned.length}</span>`,promo?'En la promoción seleccionada':'Sin promoción asignada','stores')}${stat('Pendientes de sincronizar',state.queue.length,state.queue.length?'Guardados en este dispositivo':'Todo está actualizado','sync')}</div>
  <div class="dashboard-middle"><section class="campaign-feature"><div class="feature-top"><span class="eyebrow">PROMOCIÓN EN FOCO</span>${promo?badge(active(promo)?'activa':promo.status,active(promo)?'En curso':promo.status):''}</div><h2>${esc(promo?.name||'Tu próxima promoción empieza aquí')}</h2><p>${esc(promo?.manufacturer_name||'Configura una promoción para comenzar las visitas.')}</p><div class="feature-meta"><span>${icon('clock',17)} ${promo?date(promo.start_date)+' — '+date(promo.end_date):'Sin periodo definido'}</span><span>${icon('box',17)} ${promo?.product_ids.length||0} productos</span></div><div class="feature-bottom"><a href="#${isAgent()?'stores':'promotions'}" class="button lime">${isAgent()?'Ver mis tiendas':'Gestionar promociones'} ${icon('arrow',18)}</a><span class="feature-number">${String(promo?.store_ids.length||0).padStart(2,'0')}<small>tiendas participantes</small></span></div></section><section class="panel visit-progress"><div class="panel-heading"><h2>Avance de visitas</h2>${icon('stores')}</div><div class="progress-display"><span class="progress-numerator">${done}</span><span>de ${assigned.length} tiendas<br><strong>${assigned.length?Math.round(done/assigned.length*100):0}% completado</strong></span></div><progress value="${done}" max="${assigned.length||1}" aria-label="Tiendas visitadas"></progress><div class="progress-legend"><span><i class="legend-green"></i> Visitadas <b>${done}</b></span><span><i></i> Pendientes <b>${assigned.length-done}</b></span></div><p class="note">El avance incluye visitas con pedido y visitas registradas sin pedido.</p></section></div>
  <div class="dashboard-bottom"><section class="panel"><div class="panel-heading"><div><h2>Pedidos recientes</h2><p class="muted">El resultado de tus últimas visitas</p></div><a href="#orders" class="text-link">Ver todos ${icon('arrow',16)}</a></div>${orderTable(orders.slice(0,5),true)}</section><section class="panel next-stores"><div class="panel-heading"><h2>Próximas visitas</h2><a href="#stores" class="icon-button" aria-label="Ver tiendas">${icon('arrow')}</a></div>${assigned.filter(s=>!visited(s.id,promo.id)).slice(0,3).map(s=>`<button class="visit-row" data-action="store" data-id="${s.id}"><span class="store-icon">${icon('stores')}</span><span><strong>${esc(s.name)}</strong><small>${esc(s.zone)}</small></span>${icon('arrow',16)}</button>`).join('')||empty('Visitas al día','Las visitas pendientes aparecerán aquí.','check')}<a href="#stores" class="button secondary full">Consultar directorio</a></section></div>`;
}

function storesPage(){const admin=state.data.user.role==='admin';const promo=admin?null:currentPromo();const stores=state.data.stores.filter(s=>(isAgent()?Boolean(promo?.store_ids.includes(s.id)):(!promo||promo.store_ids.includes(s.id)))&&(s.name+' '+s.address+' '+s.zone).toLowerCase().includes(state.search.toLowerCase()));return pageHeader(isAgent()?'Mis tiendas':'Directorio de tiendas','Consulta los puntos de venta y prepara tu próxima visita.',admin?'<button class="button primary" data-action="new-store">Crear tienda</button>':'')+`<div class="toolbar"><label class="search-field">${icon('search')}<input id="search" placeholder="Buscar por tienda, zona o dirección" value="${esc(state.search)}"></label>${admin?'':promoSelect()}<span class="result-count">${stores.length} tiendas</span></div><div class="store-grid">${stores.map(s=>`<article class="panel store-card"><div class="store-card-top"><span class="store-icon large">${icon('stores',25)}</span>${badge(visited(s.id,promo?.id)?'exito':'pendiente',visited(s.id,promo?.id)?'Visitada':'Por visitar')}</div><span class="record-code">${esc(s.external_code)}</span><h2>${esc(s.name)}</h2><p class="store-address">${icon('pin',17)}${esc(s.address)}</p><div class="store-details"><span>Responsable<strong>${esc(s.manager||'Sin registrar')}</strong></span><span>Cobertura<strong class="${s.coverage?'':'amber-text'}">${s.coverage?'Disponible':'Intermitente'}</strong></span></div><button class="button secondary full" data-action="store" data-id="${s.id}">Ver tienda ${icon('arrow',17)}</button>${admin?`<div class="modal-actions"><button class="button secondary" data-action="edit-store" data-id="${s.id}">Editar</button><button class="button danger-subtle" data-action="delete-store" data-id="${s.id}">Eliminar</button></div>`:''}</article>`).join('')||empty('No encontramos tiendas','Prueba otra búsqueda o revisa tus asignaciones.','stores')}</div>`;}

function productArt(p){return p.image_url&&p.image_valid?`<img src="${esc(p.image_url)}" alt="${esc(p.name)}" class="product-img" data-product-image="${p.id}">`:`<div class="product-fallback">${icon('box',40)}<span>Imagen no disponible</span></div>`;}
function catalogPage(){
  const admin=state.data.user.role==='admin';
  const promo=admin&&state.promotion==='all'?null:currentPromo();
  const products=state.data.products.filter(p=>(!promo||promo.product_ids.includes(p.id))&&(!state.favoritesOnly||favorites(uid()).has(p.id))&&(!state.category||p.category===state.category)&&(p.name+' '+p.external_code).toLowerCase().includes(state.search.toLowerCase()));
  const cats=[...new Set(state.data.products.map(p=>p.category))];
  const actions=admin?`<a class="button primary" href="#inventory">Crear desde Inventario</a>`:isAgent()?`<button class="button primary" data-action="new-order">${icon('plus')} Tomar pedido</button>`:'';
  const selector=admin?`<select id="promotion-filter" aria-label="Promoción de trabajo">${option('all','Todos los productos',promo?.id||'all')}${state.data.promotions.map(p=>option(p.id,p.name,promo?.id)).join('')}</select>`:promoSelect();
  return pageHeader('Catálogo de productos',admin?'Administra los productos y sus fotos.':'La subgama de tu promoción, lista para presentar.',actions)+`<div class="toolbar"><label class="search-field">${icon('search')}<input id="search" placeholder="Buscar productos o códigos" value="${esc(state.search)}"></label>${selector}<select id="category-filter" aria-label="Categoría">${option('','Todas las categorías',state.category)}${cats.map(c=>option(c,c,state.category)).join('')}</select></div><button class="button secondary" data-action="filter-favorites" aria-pressed="${state.favoritesOnly}">${state.favoritesOnly?'Ver todos los productos':'Ver favoritos'}</button><div class="catalog-context"><span>${products.length} productos en esta selección</span><span>${esc(promo?.manufacturer_name||'Todos los fabricantes')}</span></div><div class="product-grid">${products.map(p=>`<article class="product-card"><div class="product-art">${productArt(p)}<span class="product-category">${esc(p.category)}</span></div><div class="product-info"><span class="record-code">${esc(p.external_code)}</span><h2>${esc(p.name)}</h2><p>${esc(p.description)}</p><p class="note">${discountLabel(p)}</p><button class="button secondary favorite-button" data-action="favorite" data-id="${p.id}" aria-pressed="${favorites(uid()).has(p.id)}">${favorites(uid()).has(p.id)?'★ Quitar favorito':'☆ Guardar favorito'}</button><div class="product-bottom"><strong>${money(p.price)}</strong>${isAgent()?`<button class="icon-button add-product" data-action="new-order" data-product="${p.id}" aria-label="Agregar ${esc(p.name)} al pedido">${icon('plus')}</button>`:''}</div>${admin?`<button class="button secondary full product-edit" data-action="edit-product" data-id="${p.id}">${icon('edit',16)} Editar / subir foto</button>`:''}</div></article>`).join('')||empty('Sin productos para mostrar',admin?'Crea un producto o cambia los filtros.':'Selecciona otra promoción o cambia los filtros.','catalog')}</div>`;
}

function showProduct(id){
  if(state.data.user.role!=='admin')return;
  const p=state.data.products.find(p=>p.id===Number(id));
  const mid=p?.manufacturer_id||currentPromo()?.manufacturer_id||state.data.manufacturers[0]?.id;
  modal(`<span class="eyebrow green">ADMINISTRAR CATÁLOGO</span><h2>${p?'Editar producto y foto':'Crear producto'}</h2><form id="product-form" data-id="${p?.id||''}"><div class="form-columns"><label>Código del producto<input name="external_code" value="${esc(p?.external_code)}" required maxlength="80" placeholder="Ej. ABA-010"></label>${!p?`<label>Precio en pesos<input name="price" type="number" min="1" max="1000000000" step="1" value="${p?.price||''}" required></label>`:''}</div><label>Nombre del producto<input name="name" value="${esc(p?.name)}" required minlength="2" maxlength="160"></label><label>Descripción<textarea name="description" required maxlength="2000" rows="2">${esc(p?.description)}</textarea></label><div class="form-columns"><label>Categoría<input name="category" value="${esc(p?.category||'Cuidado diario')}" required maxlength="80"></label><label>Fabricante<select name="manufacturer_id" id="product-manufacturer" required>${state.data.manufacturers.map(m=>option(m.id,m.name,mid)).join('')}</select></label></div>${!p?`<div class="form-columns"><label>Unidad de venta<select name="unit">${['unidad','caja','frasco','tubo','paquete','blíster','kit'].map(u=>option(u,u,p?.unit||'unidad')).join('')}</select></label><label>Stock máximo sugerido (0 sin límite)<input name="stock_max" type="number" min="0" max="1000000" step="1" required value="${p?.stock_max||0}"></label></div><p class="note">Cada cantidad corresponde a esta presentación. No hay conversión entre cajas y unidades. Tras registrar movimientos, crea otro producto para usar otra unidad.</p>`:''}<label>Añadir a una promoción (opcional)<select name="promotion_id" id="product-promotion"><option value="">${p?'Conservar las asignaciones actuales':'Guardar sin asignar'}</option>${state.data.promotions.filter(p=>p.manufacturer_id===Number(mid)).map(p=>option(p.id,p.name,'')).join('')}</select></label>${!p?`<div class="form-columns"><label>Cantidad mínima para descuento<input name="discount_min" type="number" min="0" max="10000" step="1" value="${p?.discount_min||0}" required></label><label>Descuento porcentual<input name="discount_percent" type="number" min="0" max="90" step="1" value="${p?.discount_percent||0}" required></label></div><p class="note">Usa ambos valores en cero para desactivar. El descuento se aplica por producto al alcanzar la cantidad mínima.</p>`:'<p class="note">El precio, los descuentos y las existencias se gestionan en Inventario.</p>'}<div class="photo-upload"><div class="photo-preview" id="photo-preview">${p?productArt(p):`<span class="muted">Sin foto seleccionada</span>`}</div><label>Foto del producto<input id="product-photo" type="file" accept="image/jpeg,image/png,image/webp"></label><p class="note">Selecciona JPG, PNG o WebP de hasta 10 MB. Verás una vista previa antes de guardar. Si no seleccionas otra foto, se conserva la actual.</p></div><p class="form-error" role="alert"></p><div class="modal-actions"><button class="button secondary" type="button" data-action="close">Cancelar</button><button class="button primary" type="submit">Guardar producto</button></div></form>`);
}

async function preparePhoto(input){
  const form=input.form;const file=input.files[0];form._photo=null;
  if(!file)return;
  if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024)throw new Error('Selecciona una foto JPG, PNG o WebP de hasta 10 MB.');
  let bitmap;
  try{bitmap=await createImageBitmap(file);}catch{throw new Error('No se pudo abrir esa imagen. Prueba con otra foto.');}
  try{
    const scale=Math.min(1,960/bitmap.width,960/bitmap.height);
    const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));
    canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);
    const url=canvas.toDataURL('image/png');form._photo=url.split(',')[1];
    if(form.isConnected){const preview=form.querySelector('#photo-preview');preview.replaceChildren();const img=new Image();img.alt='Vista previa de la foto seleccionada';img.src=url;preview.append(img);}
  }finally{bitmap.close();}
}

