async function newOrder(storeId,productId){
  if(!isAgent())return;
  if(state.draft){showDraft();toast('Retomamos tu borrador. Puedes descartarlo para iniciar otro.');return;}
  const p=currentPromo();if(!p||!active(p))return toast('Selecciona una promoción vigente para tomar pedidos.',true);
  const stores=state.data.stores.filter(s=>p.store_ids.includes(s.id));if(!stores.length)return toast('No tienes tiendas asignadas.',true);
  const sid=Number(storeId)||stores[0].id;const s=stores.find(s=>s.id===sid)||stores[0];
  state.draft={id:crypto.randomUUID(),promotion_id:p.id,store_id:s.id,confirmed_by:s.manager,notes:'',items:[]};
  if(productId){const product=state.data.products.find(x=>x.id===Number(productId));if(product&&p.product_ids.includes(product.id))state.draft.items.push({product_id:product.id,quantity:1,unit_price:unitPrice(product,1)});}
  await saveDraft();showDraft();
}
async function saveDraft(){await write('draft:'+uid(),state.draft);}
function showDraft(){const d=state.draft;if(!d)return;const p=availablePromos().find(p=>p.id===d.promotion_id);if(!p)return toast('La promoción del borrador ya no está asignada. Contacta al administrador.',true);const store=state.data.stores.find(s=>s.id===d.store_id&&p.store_ids.includes(s.id));if(!store)return toast('La tienda ya no está asignada a esta promoción.',true);d.confirmed_by=store.manager||'';const products=state.data.products.filter(x=>p.product_ids.includes(x.id));for(const item of d.items){const product=products.find(p=>p.id===item.product_id);if(product)item.unit_price=unitPrice(product,item.quantity);}modal(`<span class="eyebrow green">CAPTURA EN TIENDA</span><h2>Nuevo pedido</h2><p class="muted">${esc(p.name)}</p><form id="order-form"><label>Tienda<select name="store_id" id="draft-store">${state.data.stores.filter(s=>p.store_ids.includes(s.id)).map(s=>option(s.id,s.name,d.store_id)).join('')}</select></label><label>Buscar producto<input type="search" data-product-search="draft-product" placeholder="Nombre o código" autocomplete="off"></label><div class="order-picker"><label>Agregar producto<select id="draft-product">${products.filter(p=>!d.items.some(i=>i.product_id===p.id)).map(p=>option(p.id,p.name+' · '+money(p.price),'')).join('')}</select></label><button type="button" class="button secondary" data-action="add-line">${icon('plus')} Agregar</button></div><div class="draft-lines">${d.items.length?d.items.map(item=>{const product=products.find(p=>p.id===item.product_id);return `<div class="draft-line"><div><strong>${esc(product?.name||'Producto retirado de la promoción')}</strong><small>${money(item.unit_price)} / unidad · ${discountLabel(product)}</small></div><label class="quantity">Cantidad<input type="number" min="1" max="10000" required value="${item.quantity}" data-quantity="${item.product_id}" aria-label="Cantidad ${esc(product?.name)}"></label><strong>${money(item.quantity*item.unit_price)}</strong><button class="icon-button" type="button" data-action="remove-line" data-id="${item.product_id}" aria-label="Quitar ${esc(product?.name)}">${icon('close',17)}</button></div>`;}).join(''):empty('Selecciona los productos','Agrega los productos elegidos por el responsable de tienda.','catalog')}</div><div class="order-total"><span>Total del pedido</span><strong>${money(d.items.reduce((s,i)=>s+i.quantity*i.unit_price,0))}</strong></div><label>Nombre del responsable que confirma<input name="confirmed_by" id="draft-manager" readonly aria-readonly="true" value="${esc(d.confirmed_by)}"></label><label>Observaciones<textarea name="notes" id="draft-notes" maxlength="1000" rows="2" placeholder="Observaciones de la visita">${esc(d.notes)}</textarea></label><label class="check-label"><input type="checkbox" name="confirmed" required> El responsable revisó los productos, cantidades y total, y confirma este pedido.</label><div class="modal-actions"><button type="button" class="button danger-subtle" data-action="discard-draft">Descartar borrador</button><button type="submit" class="button primary" ${!d.items.length?'disabled':''}>${icon('check')} Confirmar y guardar</button></div><p class="note">Puedes ajustar el borrador antes de confirmar. El pedido se guarda en este dispositivo y se envía cuando hay conexión. No borres los datos del navegador mientras haya pendientes.</p></form>`);}

function showOrder(id){const o=state.data.orders.find(o=>o.id===id);if(!o)return;modal(`<span class="eyebrow green">PEDIDO #${esc(o.id.slice(0,8).toUpperCase())}</span><h2>${esc(o.store_name)}</h2><p>${badge(o.status)} ${o.captured_offline?badge('aviso','Capturado sin conexión'):''}</p>${o.review_reason?`<div class="notice amber">${esc(o.review_reason)}</div>`:''}<div class="detail-grid"><span>Promoción<strong>${esc(o.promotion_name)}</strong></span><span>Agente<strong>${esc(o.agent_name)}</strong></span><span>Capturado<strong>${datetime(o.captured_at)}</strong></span><span>Enviado<strong>${datetime(o.sent_at)}</strong></span><span>Confirmado por<strong>${esc(o.confirmed_by)}</strong></span><span>Recepción en DP<strong>${o.dp_received_at?datetime(o.dp_received_at):'Pendiente de conector interno'}</strong></span></div><div class="table-scroll"><table><thead><tr><th>Producto</th><th>Cantidad</th><th>Precio</th><th>Subtotal</th></tr></thead><tbody>${o.items.map(i=>`<tr><td>${esc(i.product_name)}</td><td>${i.quantity}</td><td>${money(i.unit_price)}</td><td>${money(i.quantity*i.unit_price)}</td></tr>`).join('')}</tbody></table></div><div class="order-total"><span>Total</span><strong>${money(o.total)}</strong></div>${o.notes?`<p class="note">${esc(o.notes)}</p>`:''}${trackingPanel(o)}${returnPanel(o)}`);}

function checkGroup(label,name,items,selected){return `<fieldset><legend>${label}</legend><div class="checkbox-grid">${items.map(item=>`<label class="check-label"><input type="checkbox" name="${name}" value="${item.id}" ${selected.includes(item.id)?'checked':''}>${esc(item.name)}</label>`).join('')||'<p class="note">No hay registros para este fabricante.</p>'}</div></fieldset>`;}
function showPromotion(id,model){const p=model||state.data.promotions.find(p=>p.id===Number(id))||{name:'',manufacturer_id:state.data.manufacturers[0]?.id,start_date:localDate(),end_date:localDate(),status:'borrador',product_ids:[],agent_ids:[],store_ids:[]};modal(`<span class="eyebrow green">CONFIGURACIÓN COMERCIAL</span><h2>${id?'Editar promoción':'Nueva promoción'}</h2><form id="promotion-form" data-id="${id||''}"><label>Nombre<input name="name" required minlength="3" maxlength="120" value="${esc(p.name)}"></label><label>Fabricante<select name="manufacturer_id" id="promo-manufacturer">${state.data.manufacturers.map(m=>option(m.id,m.name,p.manufacturer_id)).join('')}</select></label><div class="form-columns"><label>Fecha de inicio<input name="start_date" type="date" value="${p.start_date}" required></label><label>Fecha de fin<input name="end_date" type="date" value="${p.end_date}" required></label><label>Estado<select name="status">${['borrador','activa','finalizada'].map(v=>option(v,v,p.status)).join('')}</select></label></div>${checkGroup('Subgama de productos','product_ids',state.data.products.filter(x=>x.manufacturer_id===Number(p.manufacturer_id)),p.product_ids)}${checkGroup('Agentes participantes','agent_ids',state.data.users.filter(x=>x.role==='agente'&&x.active&&x.manufacturer_id===Number(p.manufacturer_id)),p.agent_ids)}${checkGroup('Tiendas asignadas','store_ids',state.data.stores,p.store_ids)}<div id="overlap-warning"></div><p class="form-error" role="alert"></p><div class="modal-actions"><button type="button" class="button secondary" data-action="close">Cancelar</button><button type="submit" class="button primary">Guardar promoción</button></div></form>`);}
function promotionData(form){const f=new FormData(form);return {name:f.get('name'),manufacturer_id:Number(f.get('manufacturer_id')),start_date:f.get('start_date'),end_date:f.get('end_date'),status:f.get('status'),product_ids:f.getAll('product_ids').map(Number),agent_ids:f.getAll('agent_ids').map(Number),store_ids:f.getAll('store_ids').map(Number),accept_overlap:f.has('accept_overlap')};}
function showUser(id){const u=state.data.users.find(u=>u.id===Number(id))||{name:'',email:'',role:'agente',active:1,manufacturer_id:state.data.manufacturers[0]?.id};modal(`<span class="eyebrow green">ADMINISTRACIÓN DE ACCESOS</span><h2>${id?'Editar usuario':'Crear usuario'}</h2><form id="user-form" data-id="${id||''}"><label>Nombre completo<input name="name" value="${esc(u.name)}" required minlength="2" maxlength="120"></label><label>Correo electrónico<input name="email" type="email" value="${esc(u.email)}" required></label><div class="form-columns"><label>Rol<select name="role">${Object.entries(roles).map(([id,name])=>option(id,name,u.role)).join('')}</select></label><label>Fabricante (para agentes)<select name="manufacturer_id">${state.data.manufacturers.map(m=>option(m.id,m.name,u.manufacturer_id)).join('')}</select></label></div><label>${id?'Nueva contraseña (opcional)':'Contraseña inicial'}<input name="password" type="password" minlength="10" maxlength="200" autocomplete="new-password" ${id?'':'required'}></label><label class="check-label"><input type="checkbox" name="active" ${u.active?'checked':''}> Cuenta activa</label><p class="note">Entrega la contraseña inicial al usuario por un canal seguro. PharmaBoost no envía correos automáticamente.</p><p class="form-error" role="alert"></p><div class="modal-actions"><button type="button" class="button secondary" data-action="close">Cancelar</button><button class="button primary" type="submit">Guardar usuario</button></div></form>`);}

async function loadLocal(){state.queue=await read('queue:'+uid())||[];state.draft=await read('draft:'+uid())||null;}
async function cacheData(){await write('snapshot:'+uid(),state.data);await write('last-user',uid());}
async function refresh(){const fresh=await api('/bootstrap');detectOrders(fresh);state.data=fresh;connectionReady();await cacheData();}
async function enqueue(kind,payload){if(state.queue.some(item=>item.payload.id===payload.id))throw new Error('Esta operación ya está pendiente de envío.');const next=[...state.queue,{kind,payload,error:null}];await write('queue:'+uid(),next);state.queue=next;}
async function syncNow(manual=false){if(state.syncing||!state.data)return;if(!navigator.onLine){requireConnection();if(manual)toast('Conexión requerida para enviar datos.',true);render();return;}state.syncing=true;render();let sent=0;try{for(const item of [...state.queue]){try{await api('/'+item.kind,'POST',item.payload);state.queue=state.queue.filter(q=>q.payload.id!==item.payload.id);await write('queue:'+uid(),state.queue);if(item.kind==='orders'&&state.draft?.id===item.payload.id){state.draft=null;await remove('draft:'+uid());}sent++;}catch(e){item.error=e.message;await write('queue:'+uid(),state.queue);if(e.network){state.offline=true;break;}if(e.status===401){toast('Inicia sesión de nuevo para enviar los pendientes. Se conservarán en este dispositivo.',true);break;}}}await refresh();if(manual||sent)toast(sent?`${sent} operación(es) enviadas correctamente.`:'Datos actualizados.');}catch(e){if(e.network)state.offline=true;if(manual)toast(e.message,true);}finally{state.syncing=false;render();}}
async function loadAudit(query=''){try{state.audits=(await api('/audit'+query)).events;if($('#audit-results'))$('#audit-results').innerHTML=auditTable();}catch(e){toast(e.message,true);}}
function bindImages(){document.querySelectorAll('[data-product-image]').forEach(img=>{img.addEventListener('error',()=>{const pid=Number(img.dataset.productImage);img.outerHTML=`<div class="product-fallback">${icon('box',40)}<span>Imagen no disponible</span></div>`;api('/image-error','POST',{product_id:pid}).catch(()=>{});});});}

document.addEventListener('click',async e=>{const button=e.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;try{
  if(action==='favorite'){toggleFavorite(Number(button.dataset.id),uid());render();return;}
  if(action==='filter-favorites'){state.favoritesOnly=!state.favoritesOnly;render();return;}
  if(action==='new-store')return showStoreForm();
  if(action==='edit-store')return showStoreForm(Number(button.dataset.id));
  if(action==='delete-store'){const store=state.data.stores.find(s=>s.id===Number(button.dataset.id));if(state.data.user.role!=='admin'||!store)return;modal(`<h2>Eliminar tienda</h2><p>¿Eliminar ${esc(store.name)}?</p><p class="note">Solo se pueden eliminar tiendas sin promociones asignadas, pedidos, visitas ni historial. Esta acción no se puede deshacer.</p><form id="delete-store-form" data-id="${store.id}"><p class="form-error" role="alert"></p><div class="modal-actions"><button type="button" class="button secondary" data-action="close">Cancelar</button><button type="submit" class="button danger-subtle">Eliminar tienda</button></div></form>`);return;}
  if(action==='new-supplier')return showSupplier();
  if(action==='edit-supplier')return showSupplier(Number(button.dataset.id));
  if(action==='inventory-settings')return showInventorySettings(button.dataset.id);
  if(action==='stock-movement')return showStock(button.dataset.id);
  if(action==='return-order')return showReturn(button.dataset.id);
  if(action==='notifications')return showNotifications();
  if(action==='enable-notifications'){if(!('Notification' in window))return toast('Este navegador no admite avisos del sistema.',true);const result=await Notification.requestPermission();localStorage.setItem('pb-notifications:'+uid(),result==='granted'?'1':'0');toast(result==='granted'?'Avisos del navegador activados.':'Puedes usar los avisos dentro de PharmaBoost.');return;}
  if(action==='read-notifications'){state.newOrders=[];localStorage.setItem('pb-unread-orders:'+uid(),'[]');closeModal();location.hash='orders';render();return;}
  if(action==='close')return closeModal();
  if(action==='register')return showRegister();
  if(action==='auth-login')return setAuthMode(false);
  if(action==='menu')return $('.sidebar').classList.toggle('open');
  if(action==='profile'){closeModal();location.hash='profile';return;}
  if(action==='logout'){document.getElementById('print-receipt')?.remove();if(state.syncing)return toast('Espera a que termine la sincronización.',true);if(!navigator.onLine)return toast('Recupera la conexión para cerrar la sesión en el servidor.',true);await api('/logout','POST',{});await remove('last-user');await remove('snapshot:'+uid());state.data=null;state.queue=[];state.draft=null;state.newOrders=[];state.favoritesOnly=false;closeModal();return renderLogin();}
  if(action==='sync-now')return syncNow(true);
  if(action==='store')return showStore(button.dataset.id);
  if(action==='new-order'){closeModal();return newOrder(button.dataset.store,button.dataset.product);}
  if(action==='edit-draft')return showDraft();
  if(action==='add-line'){const pid=Number($('#draft-product').value);if(!pid||!state.draft)return;const promo=state.data.promotions.find(p=>p.id===state.draft.promotion_id);if(!promo?.product_ids.includes(pid)||state.draft.items.some(i=>i.product_id===pid))return;const p=state.data.products.find(p=>p.id===pid);if(!p)return;state.draft.items.push({product_id:pid,quantity:1,unit_price:unitPrice(p,1)});await saveDraft();closeModal();return showDraft();}
  if(action==='remove-line'){state.draft.items=state.draft.items.filter(i=>i.product_id!==Number(button.dataset.id));await saveDraft();closeModal();return showDraft();}
  if(action==='discard-draft'){state.draft=null;await remove('draft:'+uid());closeModal();render();return toast('Borrador descartado.');}
  if(action==='no-order'){const p=currentPromo();if(!p||!active(p))return toast('Selecciona una promoción vigente.',true);modal(`<h2>Registrar visita sin pedido</h2><p class="muted">El responsable decidió no incorporar productos en esta visita.</p><form id="visit-form" data-store="${button.dataset.id}" data-promo="${p.id}"><label>Observaciones<textarea name="notes" maxlength="1000" rows="3" placeholder="Resultado de la visita"></textarea></label><div class="modal-actions"><button class="button secondary" type="button" data-action="close">Cancelar</button><button class="button primary" type="submit">Registrar visita</button></div></form>`);return;}
  if(action==='print-order')return printOrder(button.dataset.id);
  if(action==='export-report')return exportReport();
  if(action==='xlsx-report'){downloadBlob(workbook(reportRows()),'PharmaBoost-reporte.xlsx');return;}
  if(action==='print-report'){printReport();return;}
  if(action==='report-detail'){showReportDetail(button.dataset.id);return;}
  if(action==='pdf-report'){busy(button,true);try{await downloadReportPdf();}finally{busy(button,false);}return;}
  if(action==='report-back'){state.reportSection=null;render();return;}
  if(action==='report-open'){state.reportSection=button.dataset.id;state.reportFilters={type:state.reportSection,sort:'name'};render();return;}
  if(action==='reset-report'){state.reportFilters={type:state.reportSection||'general',sort:'name'};state.reportFrom='';state.reportTo='';state.reportPromo='';state.reportAgent='';render();return;}
  if(action==='order-detail')return showOrder(button.dataset.id);
  if(action==='new-promotion')return showPromotion();
  if(action==='edit-promotion')return showPromotion(button.dataset.id);
  if(action==='select-promotion'){state.promotion=button.dataset.id;location.hash='stores';return;}
  if(action==='new-user')return showUser();
  if(action==='new-product')return showProduct();
  if(action==='edit-product')return showProduct(button.dataset.id);
  if(action==='review-registration')return showRegistration(button.dataset.id);
  if(action==='edit-user')return showUser(button.dataset.id);
  if(action==='new-manufacturer'){modal(`<h2>Registrar fabricante</h2><form id="manufacturer-form"><label>Nombre<input name="name" required minlength="2" maxlength="120"></label><label>Contacto<input name="contact" maxlength="160"></label><button class="button primary" type="submit">Guardar fabricante</button></form>`);return;}
  if(action==='export-orders'){const data=[['Pedido','Tienda','Promoción','Agente','Captura','Total COP','Estado'],...state.data.orders.map(o=>[o.id,o.store_name,o.promotion_name,o.agent_name,o.captured_at,o.total,o.status])];const safe=v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const blob=new Blob(['\ufeff'+data.map(r=>r.map(safe).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='PharmaBoost-pedidos.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Archivo CSV exportado con todos los pedidos disponibles.');}
}catch(error){toast(error.message,true);}});

document.addEventListener('input',async e=>{const el=e.target;if(el.dataset.quantity&&state.draft&&el.checkValidity()){const item=state.draft.items.find(i=>i.product_id===Number(el.dataset.quantity));item.quantity=Number(el.value);const product=state.data.products.find(p=>p.id===item.product_id);if(product)item.unit_price=unitPrice(product,item.quantity);el.closest('.draft-line').querySelector('small').textContent=money(item.unit_price)+' / unidad · '+discountLabel(product);el.closest('.draft-line').querySelector(':scope > strong').textContent=money(item.quantity*item.unit_price);$('.order-total strong').textContent=money(state.draft.items.reduce((sum,i)=>sum+i.quantity*i.unit_price,0));await saveDraft();}if(el.id==='search'){state.search=el.value;const position=el.selectionStart;$('#content').innerHTML=pageContent();$('#search').focus();$('#search').setSelectionRange(position,position);bindImages();}if(el.id==='draft-notes'){state.draft.notes=el.value;await saveDraft();}});
document.addEventListener('change',async e=>{
  const el=e.target;
  try{
    const filters={'commercial-filter':'commercial','promotion-filter':'promotion','category-filter':'category','order-status':'orderStatus','order-store':'orderStore','order-promo':'orderPromo','date-from':'from','date-to':'to'};
    if(filters[el.id]){state[filters[el.id]]=el.value;render();}
    if(el.id==='product-manufacturer'){$('#product-promotion').innerHTML=`<option value="">Conservar sin nueva asignación</option>`+state.data.promotions.filter(p=>p.manufacturer_id===Number(el.value)).map(p=>option(p.id,p.name,'')).join('');}
    if(el.id==='product-photo'){
      const form=el.form;const button=form.querySelector('[type=submit]');busy(button,true);form.querySelector('.form-error').textContent='';
      try{form._photoTask=preparePhoto(el);await form._photoTask;}catch(error){el.value='';form._photo=null;form.querySelector('.form-error').textContent=error.message;}finally{form._photoTask=null;busy(button,false);}
    }
    if(el.id==='draft-store'){state.draft.store_id=Number(el.value);state.draft.confirmed_by=state.data.stores.find(s=>s.id===Number(el.value))?.manager||'';await saveDraft();closeModal();showDraft();}
    if(el.dataset.quantity&&!el.checkValidity())el.reportValidity();
    if(el.id==='promo-manufacturer'){const form=$('#promotion-form');const data=promotionData(form);data.product_ids=[];data.agent_ids=[];const id=form.dataset.id;closeModal();showPromotion(id,data);}
  }catch(error){toast(error.message,true);}
});

document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;const submit=form.querySelector('[type=submit]');busy(submit,true);try{
  if(form.id==='store-form'){const f=new FormData(form),id=form.dataset.id;await api('/stores'+(id?'/'+id:''),id?'PUT':'POST',{...Object.fromEntries(f),coverage:f.has('coverage')});await refresh();closeModal();state.search='';render();toast('Tienda guardada. Asígnala desde Promociones para que un agente pueda visitarla.');}
  if(form.id==='delete-store-form'){await api('/stores/'+form.dataset.id,'DELETE',{});await refresh();closeModal();render();toast('Tienda eliminada.');}
  if(form.id==='supplier-form'){const f=new FormData(form),id=form.dataset.id;await api('/suppliers'+(id?'/'+id:''),id?'PUT':'POST',{...Object.fromEntries(f),active:f.has('active')});await refresh();closeModal();render();toast('Proveedor guardado.');}
  if(form.id==='inventory-settings-form'){const f=new FormData(form);await api('/inventory/settings','POST',{product_id:Number(form.dataset.id),price:Number(f.get('price')),unit:f.get('unit'),stock_max:Number(f.get('stock_max')),discount_min:Number(f.get('discount_min')),discount_percent:Number(f.get('discount_percent'))});await refresh();closeModal();render();toast('Configuración guardada.');}
  if(form.id==='stock-form'){const f=new FormData(form);await api('/inventory','POST',{request_id:form.dataset.request,product_id:Number(f.get('product_id')),kind:f.get('kind'),reason:f.get('reason'),supplier_id:f.get('supplier')?Number(f.get('supplier')):null,invoice:f.get('invoice'),...(f.get('kind')==='entrada'&&f.has('unit_cost')&&f.get('unit_cost')!==''?{unit_cost:Number(f.get('unit_cost'))}:{}),...(f.has('previous_cost')&&f.get('previous_cost')!==''?{previous_cost:Number(f.get('previous_cost'))}:{}),...(f.has('markup')&&f.get('markup')!==''?{markup:Number(f.get('markup'))}:{}),update_price:f.has('update_price'),quantity:Number(f.get('quantity')),minimum:Number(f.get('minimum')),note:f.get('note')});await refresh();closeModal();render();toast('Movimiento registrado.');}
  if(form.id==='return-form'){const f=new FormData(form),items=[...form.querySelectorAll('[data-return-product]')].map(el=>({product_id:Number(el.dataset.returnProduct),quantity:Number(el.value)})).filter(i=>i.quantity>0);await api('/returns','POST',{request_id:form.dataset.request,order_id:form.dataset.id,destination:f.get('destination'),note:f.get('note'),items});await refresh();closeModal();render();toast('Devolución registrada.');}
  if(form.id==='product-form'){
    if(form._photoTask)await form._photoTask;
    const f=new FormData(form);const payload={external_code:f.get('external_code'),name:f.get('name'),description:f.get('description'),category:f.get('category'),unit:f.get('unit'),stock_max:Number(f.get('stock_max')),price:Number(f.get('price')),manufacturer_id:Number(f.get('manufacturer_id')),promotion_id:f.get('promotion_id')?Number(f.get('promotion_id')):null,discount_min:Number(f.get('discount_min')),discount_percent:Number(f.get('discount_percent'))};
    if(form.dataset.id)for(const key of ['price','unit','stock_max','discount_min','discount_percent'])delete payload[key];
    if(form._photo)payload.photo=form._photo;
    await api((form.dataset.id?'/products/'+form.dataset.id:'/inventory/products'),form.dataset.id?'PUT':'POST',payload);
    closeModal();state.promotion=payload.promotion_id?String(payload.promotion_id):'all';state.search='';state.category='';await refresh();render();toast('Producto guardado'+(payload.photo?' con su foto.':'.'));
  }
  if(form.id==='login-form'){const f=new FormData(form);state.data=await api('/login','POST',Object.fromEntries(f));state.offline=false;connectionReady();await write('offline-until:'+uid(),Date.now()+12*60*60*1000);await cacheData();await loadLocal();state.page=isAgent()?'stores':'home';location.hash=state.page;render();await syncNow();}
  if(form.id==='register-form'){await api('/register','POST',Object.fromEntries(new FormData(form)));form.reset();setAuthMode(false);toast('Solicitud enviada. El administrador debe asignarte un rol antes de iniciar sesión.');}
  if(form.id==='registration-review-form'){const f=new FormData(form);await api('/registration-requests/'+form.dataset.id,'POST',{decision:f.get('decision'),role:f.get('role'),manufacturer_id:Number(f.get('manufacturer_id')),reason:f.get('reason')});closeModal();await refresh();render();toast('Solicitud revisada y cuenta actualizada.');}
  if(form.id==='order-form'){const f=new FormData(form);for(const input of form.querySelectorAll('[data-quantity]')){const item=state.draft.items.find(i=>i.product_id===Number(input.dataset.quantity));if(item){item.quantity=Number(input.value);const product=state.data.products.find(p=>p.id===item.product_id);if(product)item.unit_price=unitPrice(product,item.quantity);}}if(!state.draft.items.length)throw new Error('Agrega al menos un producto.');const payload={...state.draft,confirmed_by:state.data.stores.find(s=>s.id===state.draft.store_id)?.manager||'',notes:f.get('notes'),confirmed:f.has('confirmed'),captured_offline:state.offline||!navigator.onLine,captured_at:new Date().toISOString()};await enqueue('orders',payload);state.draft=null;await remove('draft:'+uid());closeModal();location.hash='orders';render();toast(state.offline?'Pedido guardado sin conexión. Se enviará al reconectar.':'Pedido guardado. Preparando envío…');await syncNow();}
  if(form.id==='visit-form'){const f=new FormData(form);await enqueue('visits',{id:(form.dataset.requestId ||= crypto.randomUUID()),store_id:Number(form.dataset.store),promotion_id:Number(form.dataset.promo),notes:f.get('notes'),created_at:new Date().toISOString()});closeModal();toast('Visita guardada.');await syncNow();}
  if(form.id==='promotion-form'){const id=form.dataset.id;await api('/promotions'+(id?'/'+id:''),id?'PUT':'POST',promotionData(form));closeModal();await refresh();render();toast('Promoción y asignaciones guardadas.');}
  if(form.id==='user-form'){const f=new FormData(form),id=form.dataset.id;await api('/users'+(id?'/'+id:''),id?'PUT':'POST',{name:f.get('name'),email:f.get('email'),role:f.get('role'),manufacturer_id:Number(f.get('manufacturer_id')),password:f.get('password'),active:f.has('active')});closeModal();try{await refresh();render();toast('Usuario guardado.');}catch(error){if(error.status===401){state.data=null;renderLogin('Tu cuenta cambió. Inicia sesión nuevamente.');}else throw error;}}
  if(form.id==='manufacturer-form'){await api('/manufacturers','POST',Object.fromEntries(new FormData(form)));closeModal();await refresh();render();toast('Fabricante registrado.');}
  if(form.id==='tracking-form'){const data=Object.fromEntries(new FormData(form));await api('/orders/'+encodeURIComponent(form.dataset.id)+'/tracking','PUT',data);await refresh();closeModal();render();showOrder(form.dataset.id);toast('Seguimiento actualizado.');}
  if(form.id==='report-filter'){const filters=Object.fromEntries(new FormData(form));if(filters.from&&filters.to&&filters.from>filters.to)throw new Error('La fecha inicial debe ser anterior o igual a la final.');state.reportFilters=filters;render();toast('Filtros aplicados.');}
  if(form.id==='profile-form'){await api('/profile','PUT',Object.fromEntries(new FormData(form)));await refresh();render();toast('Perfil actualizado.');}
  if(form.id==='audit-filter'){await loadAudit('?'+new URLSearchParams(new FormData(form)).toString());}
  if(form.id==='import-form'){const f=new FormData(form),file=f.get('file');if(file.size>2000000)throw new Error('El archivo supera 2 MB.');let data;try{data=JSON.parse(await file.text());}catch{throw new Error('El archivo no contiene JSON válido.');}const result=await api('/import/'+f.get('kind'),'POST',Array.isArray(data)?{records:data}:data);await refresh();render();$('#import-result').innerHTML=`<div class="notice">${result.accepted} registros actualizados · ${result.rejected.length} descartados.</div>${result.rejected.map(r=>`<p class="error-text">Fila ${r.row}: ${esc(r.error)}</p>`).join('')}`;}
}catch(error){if(form.id==='login-form'&&error.details?.locked_until){loginLocks.set(form.elements.email.value.trim().toLowerCase(),error.details.locked_until);setTimeout(updateLoginLock,0);}const errorEl=form.querySelector('.form-error');if(errorEl)errorEl.textContent=error.message;else toast(error.message,true);if(form.id==='promotion-form'&&error.details){$('#overlap-warning').innerHTML=`<div class="notice amber"><div><strong>Revisa el solapamiento</strong><p>${error.details.map(p=>esc(p.name)).join(', ')}</p><label class="check-label"><input type="checkbox" name="accept_overlap"> He revisado el conflicto y autorizo guardar las asignaciones.</label></div></div>`;}}finally{busy(submit,false);}});

window.addEventListener('hashchange',()=>{state.page=location.hash.slice(1)||'home';if(!titles[state.page])state.page='home';state.search='';render();if(state.page==='audit'&&state.data)loadAudit();window.scrollTo(0,0);});
window.addEventListener('online',()=>{if(state.data)syncNow();else init();});
window.addEventListener('offline',()=>{requireConnection();if(state.data)render();});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const rect=$('#modal').getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeModal();}});
async function init(){try{await api('/health');await refresh();await loadLocal();state.page=location.hash.slice(1)||'home';if(!titles[state.page])state.page='home';render();if(state.page==='audit')await loadAudit();await syncNow();}catch(error){if(error.network){const userId=await read('last-user'),until=await read('offline-until:'+userId);if(userId&&until>Date.now()){state.data=await read('snapshot:'+userId);if(state.data){await loadLocal();state.offline=true;state.page=location.hash.slice(1)||'home';if(!titles[state.page])state.page='home';render();return;}}}renderLogin(error.network?'Conéctate para iniciar sesión y preparar tu acceso sin conexión.':error.status===503?error.message:'');}}
if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js',{updateViaCache:'none'}).catch(()=>toast('No se pudo actualizar la caché de la aplicación. Recarga la página.',true));
setInterval(()=>{if(state.data&&navigator.onLine&&state.queue.length&&!$('#modal').open)syncNow();},30000);
init().catch(error=>{renderLogin();toast('No se pudo abrir el almacenamiento local. Permite los datos del sitio en tu navegador.',true);});

function trackingPanel(o){
 const current=o.commercial_status||'pendiente',next=(transitions[current]||[]).filter(v=>o.status!=='revision'||v==='cancelado');
 return `<section class="tracking-panel"><h3>Seguimiento comercial · ${esc(stages[current])}</h3><p class="note">Registro manual de la gestión comercial. No confirma recepción automática en DP.</p><ol class="tracking-history"><li>Pedido recibido · Pendiente<small>${datetime(o.sent_at)}</small></li>${(o.history||[]).map(h=>`<li>${esc(stages[h.state])}<small>${datetime(h.created_at)} · ${esc(h.actor)}</small>${esc(h.note)}</li>`).join('')}</ol>${manage()&&next.length?`<form id="tracking-form" data-id="${esc(o.id)}"><input type="hidden" name="expected" value="${esc(current)}"><label>Nuevo estado<select name="state">${next.map(v=>option(v,stages[v],'')).join('')}</select></label><label>Observación del cambio<textarea name="note" minlength="3" maxlength="500" required placeholder="Indica el motivo o la referencia de la gestión"></textarea></label><p class="form-error" role="alert"></p><button type="submit" class="button primary" ${state.offline?'disabled':''}>Guardar seguimiento</button></form>`:''}<div class="modal-actions"><button type="button" class="button secondary" data-action="print-order" data-id="${esc(o.id)}">Imprimir comprobante / PDF</button></div></section>`;
}
function printOrder(id){
 const o=state.data.orders.find(o=>o.id===id);if(!o)return;
 document.getElementById('print-receipt')?.remove();const sheet=document.createElement('section');sheet.id='print-receipt';sheet.className='print-only';
 sheet.innerHTML=`<h1>PharmaBoost</h1><h2>Comprobante de pedido</h2><p><strong>Pedido:</strong> ${esc(o.id)}<br><strong>Tienda:</strong> ${esc(o.store_name)}<br><strong>Promoción:</strong> ${esc(o.promotion_name)}<br><strong>Agente:</strong> ${esc(o.agent_name)}<br><strong>Fecha:</strong> ${datetime(o.captured_at)}<br><strong>Confirmado por:</strong> ${esc(o.confirmed_by)}<br><strong>Seguimiento:</strong> ${esc(stages[o.commercial_status||'pendiente'])}<br><strong>Recepción:</strong> ${o.status==='revision'?'En revisión de precios':'Registrado en PharmaBoost'}</p>${o.review_reason?`<p>${esc(o.review_reason)}</p>`:''}<table><thead><tr><th>Producto</th><th>Cantidad</th><th>Precio COP</th><th>Subtotal COP</th></tr></thead><tbody>${o.items.map(i=>`<tr><td>${esc(i.product_name)}</td><td>${i.quantity}</td><td>${money(i.unit_price)}</td><td>${money(i.quantity*i.unit_price)}</td></tr>`).join('')}</tbody></table><p class="receipt-total">Total: ${money(o.total)}</p><p>${esc(o.notes)}</p><p>Comprobante informativo. No es factura ni prueba de pago o de recepción por DP.</p>`;
 document.body.append(sheet);const dialog=$('#modal'),wasOpen=dialog.open;if(wasOpen)dialog.close();window.print();if(wasOpen)dialog.showModal();
}
function reportOrders(){return state.data.orders.filter(o=>(!state.reportFrom||o.captured_at.slice(0,10)>=state.reportFrom)&&(!state.reportTo||o.captured_at.slice(0,10)<=state.reportTo)&&(!state.reportPromo||String(o.promotion_id)===state.reportPromo)&&(!state.reportAgent||String(o.agent_id)===state.reportAgent));}
function reportScope(){return `Aplicado: ${state.reportFrom||'Sin fecha inicial'} hasta ${state.reportTo||'Sin fecha final'} · ${state.data.promotions.find(p=>String(p.id)===state.reportPromo)?.name||'Todas las promociones'} · ${state.data.orders.find(o=>String(o.agent_id)===state.reportAgent)?.agent_name||'Todos los agentes'}`;}
function discountLabel(p){return p?.discount_percent?`${p.discount_percent}% desde ${p.discount_min} unidades`: 'Sin descuento por cantidad';}
const costMoney=n=>new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',minimumFractionDigits:2,maximumFractionDigits:2}).format(n);
function inventoryPage(){
 if(!manage())return empty('Acceso reservado');
 const products=state.data.products.filter(p=>(p.name+' '+p.external_code).toLowerCase().includes(state.search.toLowerCase()));
 const low=state.data.products.filter(p=>p.stock_enabled&&p.stock<=p.stock_min);
 return pageHeader('Inventario','Existencias y ganancia bruta estimada por unidad, antes de impuestos y gastos.',`${state.data.user.role==='admin'?'<button class="button secondary" data-action="new-product">Crear producto</button>':''}<button class="button primary" data-action="stock-movement">Registrar movimiento</button>`)+`<p class="notice">${low.length} productos en el mínimo o por debajo. Los pedidos no reservan stock; las unidades salen al despachar. Registra las existencias reales antes del primer despacho.</p><div class="toolbar"><label class="search-field">${icon('search')}<input id="search" placeholder="Buscar producto o código" value="${esc(state.search)}"></label></div><section class="panel"><div class="table-scroll"><table><thead><tr><th>Producto</th><th>Disponible</th><th>Costo promedio</th><th>Precio venta</th><th>Ganancia por unidad</th><th>Mínimo / máximo</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${products.map(p=>`<tr><td>${esc(p.name)}<small>${esc(p.external_code)}</small></td><td>${p.stock_enabled?p.stock:'Sin registrar'}</td><td>${p.average_cost==null?'Sin valorar':costMoney(p.average_cost)}</td><td>${money(p.price)}</td><td>${p.average_cost==null?'Registra el costo':costMoney(p.price-p.average_cost)+'<small>Con descuento: '+costMoney(unitPrice(p,p.discount_min||1)-p.average_cost)+'</small>'}</td><td>${p.stock_min||0} / ${p.stock_max||'—'}<small>${esc(p.unit||'unidad')}${p.stock_max&&p.stock>p.stock_max?' · Sobre máximo':''}</small></td><td>${p.stock_enabled?badge(p.stock<=p.stock_min?'aviso':'exito',p.stock<=p.stock_min?'Stock bajo':'Disponible'):badge('aviso','Registra entrada inicial')}</td><td><button class="button secondary" data-action="stock-movement" data-id="${p.id}">Movimiento</button>${state.data.user.role==='admin'?`<button class="button secondary" data-action="inventory-settings" data-id="${p.id}">Precio y configuración</button><button class="button secondary" data-action="edit-product" data-id="${p.id}">Editar foto</button>`:''}</td></tr>`).join('')}</tbody></table></div></section><section class="panel operation-history"><div class="panel-heading"><h2>Últimos 200 movimientos</h2></div><div class="table-scroll"><table><thead><tr><th>Fecha / usuario</th><th>Producto</th><th>Tipo</th><th>Unidades</th><th>Observación</th></tr></thead><tbody>${(state.data.inventory_events||[]).map(r=>`<tr><td>${datetime(r.created_at)}<small>${esc(r.actor)}</small></td><td>${esc(state.data.products.find(p=>p.id===r.product_id)?.name||r.product_id)}</td><td>${esc(r.kind)}<small>${esc(r.reason||'')} · ${esc(r.supplier||'')} ${esc(r.invoice||'')}</small></td><td>${r.delta>0?'+':''}${r.delta}</td><td>${esc(r.note)}</td></tr>`).join('')||'<tr><td colspan="5">Todavía no hay movimientos.</td></tr>'}</tbody></table></div></section>`;
}
function suppliersPage(){if(!manage())return empty('Acceso reservado');const rows=(state.data.suppliers||[]).filter(s=>(s.name+' '+s.tax_id+' '+s.contact).toLowerCase().includes(state.search.toLowerCase()));return pageHeader('Proveedores','Registra los proveedores que utilizarás en las compras de inventario.',`<button class="button primary" data-action="new-supplier">${icon('plus')} Crear proveedor</button>`)+`<div class="toolbar"><label class="search-field">${icon('search')}<input id="search" placeholder="Buscar proveedor, identificación o contacto" value="${esc(state.search)}"></label></div><section class="panel"><div class="table-scroll"><table><thead><tr><th>Proveedor</th><th>Contacto</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${rows.map(s=>`<tr><td>${esc(s.name)}<small>${esc(s.tax_id)}</small></td><td>${esc(s.contact)}<small>${esc(s.phone)} · ${esc(s.email)}</small></td><td>${badge(s.active?'exito':'finalizada',s.active?'Activo':'Inactivo')}</td><td><button class="button secondary" data-action="edit-supplier" data-id="${s.id}">Editar</button></td></tr>`).join('')||'<tr><td colspan="4">No hay proveedores para mostrar. Crea uno para registrar compras.</td></tr>'}</tbody></table></div></section>`;}
function showSupplier(id){if(!manage())return;const s=(state.data.suppliers||[]).find(s=>s.id===id)||{active:true};modal(`<h2>${id?'Editar':'Crear'} proveedor</h2><form id="supplier-form" data-id="${id||''}"><label>Nombre o razón social<input name="name" minlength="2" maxlength="160" required value="${esc(s.name)}"></label><label>NIT o identificación<input name="tax_id" maxlength="40" value="${esc(s.tax_id)}"></label><label>Persona de contacto<input name="contact" maxlength="120" value="${esc(s.contact)}"></label><div class="form-columns"><label>Teléfono<input name="phone" maxlength="80" value="${esc(s.phone)}"></label><label>Correo<input name="email" type="email" maxlength="160" value="${esc(s.email)}"></label></div><label>Dirección<input name="address" maxlength="300" value="${esc(s.address)}"></label><label class="check-label"><input name="active" type="checkbox" ${s.active?'checked':''}> Proveedor activo</label><p class="note">Solo los proveedores activos aparecen al registrar movimientos. Desactivarlo conserva el historial.</p><p class="form-error" role="alert"></p><button class="button primary" type="submit">Guardar proveedor</button></form>`);}
function updateStockFields(){
 const form=$('#stock-form');if(!form)return;
 const fields=form.elements,entry=fields.kind.value==='entrada',old=fields.reason.value;
 const reasons=entry?[['ajuste_manual','Ajuste manual'],['compra_proveedor','Compra a proveedor'],['inventario_inicial','Inventario inicial']]:[['ajuste_manual','Ajuste manual'],['merma','Merma']];
 const chosen=reasons.some(([id])=>id===old)?old:'ajuste_manual';fields.reason.innerHTML=reasons.map(([id,label])=>option(id,label,chosen)).join('');
 const product=state.data.products.find(p=>p.id===Number(fields.product_id.value));
 for(const name of ['supplier','unit_cost','markup','previous_cost','update_price']){const field=fields[name];field.disabled=!entry;field.closest('label').hidden=!entry;}
 if(!entry)fields.update_price.checked=false;
 const purchase=entry&&chosen==='compra_proveedor';fields.supplier.required=purchase;fields.supplier.minLength=purchase?2:0;
 fields.unit_cost.required=entry&&(purchase||fields.update_price.checked);fields.markup.required=entry&&fields.update_price.checked;
 const previous=entry&&product?.stock>0&&product.average_cost==null;fields.previous_cost.closest('label').hidden=!previous;fields.previous_cost.disabled=!previous;fields.previous_cost.required=previous&&fields.unit_cost.value!=='';
 for(const columns of form.querySelectorAll('.form-columns'))columns.hidden=[...columns.children].every(c=>c.hidden);
}
function showStock(id){if(!manage())return;const p=state.data.products.find(p=>p.id===Number(id))||state.data.products[0];if(!p)return toast('Crea un producto primero.',true);modal(`<h2>Registrar movimiento</h2><form id="stock-form" data-request="${crypto.randomUUID()}"><label>Buscar producto<input type="search" data-product-search="stock-product" placeholder="Nombre o código"></label><label>Producto<select name="product_id" id="stock-product" required>${state.data.products.map(x=>option(x.id,x.name,p.id)).join('')}</select></label><label>Tipo<select name="kind"><option value="entrada">Entrada a existencias</option><option value="salida">Salida de existencias</option></select></label><label>Motivo<select name="reason"><option value="ajuste_manual">Ajuste manual</option><option value="compra_proveedor">Compra a proveedor (entrada)</option><option value="inventario_inicial">Inventario inicial (entrada)</option><option value="merma">Merma (salida)</option></select></label><div class="form-columns"><label>Proveedor<select name="supplier"><option value="">Selecciona un proveedor</option>${(state.data.suppliers||[]).filter(s=>s.active).map(s=>option(s.id,s.name,'')).join('')}</select></label><label>Factura o referencia<input name="invoice" maxlength="100"></label></div><div class="form-columns"><label>Costo de compra por unidad COP<input name="unit_cost" type="number" min="0" max="1000000000" step="0.01"></label><label>Porcentaje sobre costo<input name="markup" type="number" min="0" max="1000" step="0.01" value="${p.markup??''}"></label></div><label>Costo unitario del stock anterior si no está valorado<input name="previous_cost" type="number" min="0" max="1000000000" step="0.01"></label><label class="check-label"><input name="update_price" type="checkbox"> Calcular precio de venta con el costo promedio y el porcentaje</label><p class="note">Ejemplo: costo $10.000 + 30% = precio $13.000 y ganancia bruta $3.000. El precio se redondea al peso. Una entrada sin costo deja la valoración pendiente. Las salidas no requieren costo de compra.</p><div class="form-columns"><label>Unidades<input name="quantity" type="number" min="1" max="1000000" step="1" required></label><label>Stock mínimo<input name="minimum" type="number" min="0" max="1000000" step="1" value="${p.stock_min||0}" required></label></div><label>Motivo o referencia<textarea name="note" minlength="3" maxlength="500" required></textarea></label><p class="note">Crea tus proveedores desde el apartado Proveedores antes de registrar una compra. Registra cantidades verificadas. Las devoluciones vinculadas a pedidos se registran desde Devoluciones.</p><p class="form-error" role="alert"></p><button class="button primary" type="submit">Guardar movimiento</button></form>`);$('#stock-product').addEventListener('change',e=>{const selected=state.data.products.find(p=>p.id===Number(e.target.value));$('#stock-form [name=minimum]').value=selected?.stock_min||0;$('#stock-form [name=markup]').value=selected?.markup??'';$('#stock-form [name=previous_cost]').value='';$('#stock-form [name=unit_cost]').value='';updateStockFields();});for(const name of ['kind','reason','update_price','unit_cost'])$('#stock-form [name='+name+']').addEventListener('change',updateStockFields);updateStockFields();}
function returnedQuantity(o,pid){return (o.returns||[]).reduce((sum,r)=>sum+r.items.filter(i=>i.product_id===pid).reduce((s,i)=>s+i.quantity,0),0);}
function returnPanel(o){return `<section class="tracking-panel"><h3>Devoluciones</h3>${(o.returns||[]).map(r=>`<p>${datetime(r.created_at)} · ${esc(r.actor)} · ${esc(r.destination)} · ${money(r.total)}<br>${esc(r.note)}<br>${r.items.map(i=>esc(o.items.find(p=>p.product_id===i.product_id)?.product_name)+': '+i.quantity).join(' · ')}</p>`).join('')||'<p class="note">Sin devoluciones registradas.</p>'}${manage()&&o.commercial_status==='entregado'&&o.items.some(i=>returnedQuantity(o,i.product_id)<i.quantity)?`<button class="button secondary" data-action="return-order" data-id="${esc(o.id)}">Registrar devolución</button>`:''}</section>`;}
function returnsPage(){if(!manage())return empty('Acceso reservado');const rows=state.data.orders.flatMap(o=>(o.returns||[]).map(r=>({...r,store:o.store_name}))).sort((a,b)=>b.created_at.localeCompare(a.created_at));return pageHeader('Devoluciones','Registra unidades recibidas de pedidos entregados. No genera reembolsos.')+`<section class="panel padded"><h2>Seleccionar pedido entregado</h2>${state.data.orders.filter(o=>o.commercial_status==='entregado').map(o=>`<p><button class="button secondary" data-action="return-order" data-id="${esc(o.id)}">${esc(o.store_name)} · ${esc(o.id)}</button></p>`).join('')||'<p class="note">Primero registra la entrega desde el seguimiento del pedido.</p>'}</section><section class="panel operation-history"><div class="panel-heading"><h2>Historial de devoluciones</h2></div><div class="table-scroll"><table><thead><tr><th>Fecha</th><th>Tienda / pedido</th><th>Destino</th><th>Valor</th><th>Motivo</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${datetime(r.created_at)}</td><td>${esc(r.store)}<small>${esc(r.order_id)}</small></td><td>${esc(r.destination)}</td><td>${money(r.total)}</td><td>${esc(r.note)}</td></tr>`).join('')||'<tr><td colspan="5">Sin devoluciones.</td></tr>'}</tbody></table></div></section>`;}
function showReturn(id){if(!manage())return;const o=state.data.orders.find(o=>o.id===id);if(!o||o.commercial_status!=='entregado')return toast('Selecciona un pedido entregado.',true);const items=o.items.filter(i=>returnedQuantity(o,i.product_id)<i.quantity);if(!items.length)return toast('Todas las unidades ya fueron devueltas.',true);closeModal();modal(`<h2>Registrar devolución</h2><p>${esc(o.store_name)} · ${esc(o.id)}</p><form id="return-form" data-id="${esc(o.id)}" data-request="${crypto.randomUUID()}">${items.map(i=>`<label>${esc(i.product_name)} · máximo ${i.quantity-returnedQuantity(o,i.product_id)}<input data-return-product="${i.product_id}" type="number" min="0" max="${i.quantity-returnedQuantity(o,i.product_id)}" step="1" value="0" required></label>`).join('')}<label>Destino<select name="destination"><option value="cuarentena">Cuarentena — no aumenta el stock disponible</option><option value="reintegrar">Reintegrar a existencias disponibles</option></select></label><p class="note">Reintegra únicamente unidades verificadas y aptas para venta. Esta versión no controla lotes ni vencimientos. Los pedidos históricos sin salida de inventario solo admiten cuarentena.</p><label>Motivo<textarea name="note" minlength="3" maxlength="500" required></textarea></label><p class="form-error" role="alert"></p><button class="button primary" type="submit">Confirmar devolución</button></form>`);}
function detectOrders(fresh){
 if(!['admin','ventas'].includes(fresh.user.role))return;
 if(state.data?.user.id!==fresh.user.id)state.newOrders=[];
 const key='pb-seen-orders:'+fresh.user.id;try{state.newOrders=JSON.parse(localStorage.getItem('pb-unread-orders:'+fresh.user.id)||'[]');if(!Array.isArray(state.newOrders))state.newOrders=[];const raw=localStorage.getItem(key),seen=new Set(JSON.parse(raw||'[]'));const incoming=raw?fresh.orders.filter(o=>!seen.has(o.id)):[];
 if(incoming.length){state.newOrders=[...new Set([...state.newOrders,...incoming.map(o=>o.id)])];toast(`${incoming.length} pedido(s) nuevo(s) recibido(s).`);if('Notification' in window&&Notification.permission==='granted'&&localStorage.getItem('pb-notifications:'+fresh.user.id)==='1'){try{new Notification('PharmaBoost',{body:`${incoming.length} pedido(s) nuevo(s). Abre Pedidos para revisarlos.`,tag:'pharmaboost-orders'});}catch{}}}
 localStorage.setItem('pb-unread-orders:'+fresh.user.id,JSON.stringify(state.newOrders));localStorage.setItem(key,JSON.stringify(fresh.orders.map(o=>o.id)));const count=$('#notification-count');if(count)count.textContent=state.newOrders.length;
 }catch{/* Browsers without persistent storage can still use manual synchronization. */}
}
function showNotifications(){if(!manage())return;modal(`<h2>Avisos de nuevos pedidos</h2><p>${state.newOrders.length} pedido(s) nuevo(s) detectado(s).</p>${state.newOrders.map(id=>{const o=state.data.orders.find(o=>o.id===id);return o?`<p>${esc(o.store_name)} · ${money(o.total)}<br><small>${esc(o.id)}</small></p>`:'';}).join('')}<p class="note">Se revisa cada 30 segundos mientras PharmaBoost está abierto y no hay un formulario modal. No funciona con el navegador cerrado. El primer acceso establece la lista inicial sin avisar de pedidos antiguos.</p><div class="modal-actions"><button class="button secondary" data-action="enable-notifications">Activar avisos del navegador</button><button class="button primary" data-action="read-notifications">Ver pedidos y marcar leídos</button></div>`);}
setInterval(async()=>{if(state.data&&manage()&&navigator.onLine&&!state.syncing&&!$('#modal').open){try{await refresh();}catch{}}},30000);
function currentReport(){return buildReport(state.data,state.reportFilters);}
function reportRows(){return [...reportExport(currentReport(),readableReportFilters()),[],['Datos sincronizados',datetime(state.data.synced_at)]];}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
async function downloadReportPdf(){if(!manage())return;const report=currentReport(),rows=reportRows().filter(row=>JSON.stringify(row)!==JSON.stringify(report.headers)).flatMap(row=>row.length>3?[['Registro'],...row.map((v,i)=>[report.headers[i]||'Dato',v])]:[row]);const {createReportPdf}=await import('./report-pdf.js');downloadBlob(new Blob([await createReportPdf(rows,new Date().toLocaleString('es-CO'))],{type:'application/pdf'}),'PharmaBoost-reporte.pdf');toast('PDF descargado.');}
function printReport(){if(!manage())return;document.getElementById('print-receipt')?.remove();const r=currentReport(),sheet=document.createElement('section');sheet.id='print-receipt';sheet.className='print-only report-print';sheet.innerHTML='<h1>PharmaBoost</h1><h2>'+esc(r.title)+'</h2><p>'+esc(readableReportFilters())+'</p><p>Datos sincronizados: '+esc(datetime(state.data.synced_at))+'</p><dl>'+r.totals.map(([k,v])=>'<dt>'+esc(k)+'</dt><dd>'+esc(k.includes('COP')?costMoney(v):v)+'</dd>').join('')+'</dl><p>'+esc(r.note)+'</p><table><thead><tr>'+r.headers.map(h=>'<th>'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+r.records.map(row=>'<tr>'+row.cells.map((v,i)=>'<td>'+esc(typeof v==='number'&&r.headers[i].includes('COP')?costMoney(v):v)+'</td>').join('')+'</tr>').join('')+'</tbody></table>';document.body.append(sheet);window.print();}
function readableReportFilters(){const f=state.reportFilters,d=state.data,parts=[];const labels={from:'Desde',to:'Hasta',product:'Producto',category:'Categoría',store:'Tienda',agent:'Usuario',supplier:'Proveedor',promotion:'Promoción',status:'Estado',stock:'Existencias',search:'Búsqueda',sort:'Orden'};const lists={product:d.products,store:d.stores,agent:d.users,supplier:d.suppliers||[],promotion:d.promotions};const names={available:'Disponibles',empty:'Agotados',low:'Bajo mínimo',high:'Sobre máximo',unknown:'Sin registrar',name:'Nombre A–Z',date:'Fecha reciente',value:'Mayor valor',...stages};for(const [key,label]of Object.entries(labels)){if(!f[key])continue;const value=lists[key]?lists[key].find(x=>String(x.id)===String(f[key]))?.name||f[key]:names[f[key]]||f[key];parts.push(label+': '+value);}return parts.join(' · ')||'Sin filtros';}
function showReportDetail(id){if(!manage())return;const r=currentReport(),record=r.records[Number(id)];if(!record)return;if(state.reportFilters.type==='orders')return showOrder(record.detail);modal(`<h2>Detalle del registro</h2>${record.cells.map((v,i)=>`<p><strong>${esc(r.headers[i])}:</strong> ${esc(v)}</p>`).join('')}<p class="note">${esc(r.note)}</p>`);}
function reportsPage(){
 if(!manage())return empty('Acceso reservado');
 if(!state.reportSection)return pageHeader('Centro de reportes','Elige el apartado que necesitas consultar.')+`<div class="report-sections">${Object.entries(reportTypes).map(([id,name])=>`<button class="panel report-section" data-action="report-open" data-id="${id}"><h2>${esc(name)}</h2><p>${esc({general:'Indicadores globales y productos.',orders:'Pedidos por tienda, agente y producto.',inventory:'Existencias, mínimos y valoración.',movements:'Entradas, salidas y saldos por producto.',purchases:'Compras y costos por proveedor.'}[id])}</p><span>Abrir reporte →</span></button>`).join('')}</div>`;
 const f=state.reportFilters,r=currentReport(),type=f.type;

 const allowed={general:['product','category','store','agent','promotion','status','stock'],orders:['product','category','store','agent','promotion','status'],inventory:['product','category','stock'],movements:['product','category','agent','supplier'],purchases:['product','category','agent','supplier']}[type];
 const select=(name,label,items)=>!allowed.includes(name)?'':`<label>${label.split(' · ')[0]}${name==='product'?'<input type="search" data-product-search="report-product" placeholder="Buscar por nombre o código" aria-label="Buscar producto del reporte">':''}<select name="${name}" ${name==='product'?'id="report-product"':''}>${option('','Todos',f[name])}${items.map(([id,name])=>option(id,name,f[name])).join('')}</select></label>`;
 return pageHeader(r.title,'Consulta y exporta este reporte.',`<button class="button secondary" data-action="report-back">← Todos los reportes</button><button class="button secondary" data-action="export-report">CSV</button><button class="button secondary" data-action="xlsx-report">Excel</button><button class="button secondary" data-action="print-report">Imprimir</button><button class="button primary" data-action="pdf-report">PDF</button>`)+`<form id="report-filter" class="panel report-filter"><div class="toolbar wrap"><input type="hidden" name="type" value="${esc(type)}">${type!=='inventory'?`<label>Desde<input type="date" name="from" value="${esc(f.from)}"></label><label>Hasta<input type="date" name="to" value="${esc(f.to)}"></label>`:''}${select('product','Producto',state.data.products.map(p=>[p.id,p.name]))}${select('category','Categoría',[...new Set(state.data.products.map(p=>p.category))].map(c=>[c,c]))}${select('store','Tienda cliente · pedidos',state.data.stores.map(s=>[s.id,s.name]))}${select('agent','Usuario · pedidos y movimientos',state.data.users.map(u=>[u.id,u.name]))}${select('supplier','Proveedor · movimientos y compras',(state.data.suppliers||[]).map(s=>[s.id,s.name]))}${select('promotion','Promoción · pedidos',state.data.promotions.map(p=>[p.id,p.name]))}${select('status','Estado · pedidos',Object.entries(stages))}${select('stock','Existencias · inventario',[['available','Disponibles'],['empty','Agotados'],['low','Por debajo del mínimo'],['high','Sobre máximo sugerido'],['unknown','Sin registrar']])}<label>Buscar<input name="search" maxlength="160" value="${esc(f.search)}" placeholder="Producto, tienda, factura o referencia"></label><label>Orden<select name="sort">${[['name','Nombre A–Z'],['date','Fecha reciente'],['value','Mayor valor']].map(([id,name])=>option(id,name,f.sort)).join('')}</select></label><button class="button primary" type="submit">Aplicar filtros</button><button class="button secondary" type="button" data-action="reset-report">Limpiar</button></div><p class="form-error" role="alert"></p><p class="note">Filtros de este apartado. Fechas de Colombia. Pulsa Aplicar filtros antes de exportar. Inventario muestra existencias actuales.</p></form><h2>${esc(r.title)}</h2><p class="note">${esc(r.note)} Datos: ${datetime(state.data.synced_at)} ${state.offline?'· Sin conexión':''}</p><div class="stats-grid">${r.totals.map(([label,value])=>stat(label,label.includes('COP')?money(value):value,'Según alcance del reporte','box')).join('')}</div><section class="panel"><div class="table-scroll"><table><thead><tr>${r.headers.map(h=>'<th>'+esc(h)+'</th>').join('')}<th>Detalle</th></tr></thead><tbody>${r.records.map((row,i)=>`<tr>${row.cells.map(c=>'<td>'+esc(c)+'</td>').join('')}<td><button class="button secondary" data-action="report-detail" data-id="${i}">Ver detalle</button></td></tr>`).join('')||`<tr><td colspan="${r.headers.length+1}">No hay registros con estos filtros.</td></tr>`}</tbody></table></div></section>`;
}
function exportReport(){
 if(!manage())return;const rows=reportRows();
 const safe=v=>'"'+(/^[=+@\-\t\r]/.test(String(v))?"'":'')+String(v??'').replaceAll('"','""')+'"';
 const url=URL.createObjectURL(new Blob(['\ufeff'+rows.map(r=>r.map(safe).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='PharmaBoost-reporte-comercial.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}



setInterval(async()=>{if(!state.data||document.hidden)return;try{await api('/health');if(state.offline){await refresh();render();}}catch{}},15000);

function showInventorySettings(id){
 if(state.data.user.role!=='admin')return;
 const p=state.data.products.find(p=>p.id===Number(id));if(!p)return;
 modal(`<h2>Precio y configuración de inventario</h2><p>${esc(p.name)}</p><form id="inventory-settings-form" data-id="${p.id}"><label>Precio de venta COP<input name="price" type="number" min="1" max="1000000000" step="1" required value="${p.price}"></label><label>Unidad de venta<select name="unit">${['unidad','caja','frasco','tubo','paquete','blíster','kit'].map(u=>option(u,u,p.unit||'unidad')).join('')}</select></label><label>Máximo sugerido (0 sin definir)<input name="stock_max" type="number" min="0" max="1000000" step="1" required value="${p.stock_max||0}"></label><label>Cantidad mínima para descuento<input name="discount_min" type="number" min="0" max="10000" step="1" required value="${p.discount_min||0}"></label><label>Descuento porcentual<input name="discount_percent" type="number" min="0" max="90" step="1" required value="${p.discount_percent||0}"></label><p class="note">Usa ambos descuentos en cero para desactivar. Las existencias y el mínimo se modifican con Registrar movimiento. No puedes cambiar la unidad si ya tiene movimientos.</p><p class="form-error" role="alert"></p><button class="button primary" type="submit">Guardar configuración</button></form>`);
}

document.addEventListener('input',e=>{const input=e.target,id=input.dataset.productSearch;if(!id)return;const select=document.getElementById(id);if(!select)return;const norm=v=>String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),term=norm(input.value);const promo=id==='draft-product'?state.data.promotions.find(p=>p.id===state.draft?.promotion_id):null;const matches=state.data.products.filter(p=>(id!=='draft-product'||(promo?.product_ids.includes(p.id)&&!state.draft.items.some(i=>i.product_id===p.id)))&&norm(p.name+' '+p.external_code).includes(term.trim()));const selected=select.value;select.innerHTML=option('',id==='report-product'?'Todos':'Selecciona un producto','')+matches.map(p=>option(p.id,p.name+' · '+p.external_code+(id==='draft-product'?' · '+money(p.price):''),selected)).join('');if(!matches.some(p=>String(p.id)===selected))select.value='';select.dispatchEvent(new Event('change',{bubbles:true}));let note=input.parentElement.querySelector('.search-count');if(!note){note=document.createElement('small');note.className='search-count';note.setAttribute('role','status');input.parentElement.append(note);}note.textContent=matches.length+' productos encontrados';});

// Buscar no debe confirmar el formulario de pedido al pulsar Enter.
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.dataset.productSearch==='draft-product')e.preventDefault();});

function showStoreForm(id){
 if(state.data.user.role!=='admin')return;
 const store=state.data.stores.find(s=>s.id===id)||{coverage:true};
 modal(`<h2>${id?'Editar':'Crear'} tienda</h2><form id="store-form" data-id="${id||''}"><label>Código externo<input name="external_code" value="${esc(store.external_code)}" maxlength="80" required></label><label>Nombre<input name="name" value="${esc(store.name)}" minlength="2" maxlength="160" required></label><label>Dirección<input name="address" value="${esc(store.address)}" minlength="2" maxlength="300" required></label><div class="form-columns"><label>Zona<input name="zone" value="${esc(store.zone)}" maxlength="120"></label><label>Teléfono<input name="phone" type="tel" value="${esc(store.phone)}" maxlength="80"></label></div><label>Responsable de la tienda<input name="manager" value="${esc(store.manager)}" minlength="2" maxlength="120" required></label><p class="note">Solo Administración puede corregir este dato aquí. El agente no puede cambiarlo al tomar un pedido. Los pedidos anteriores conservan el responsable registrado en ese momento.</p><label class="check-label"><input type="checkbox" name="coverage" ${store.coverage?'checked':''}> Cobertura disponible</label><p class="note">Crear la tienda no la asigna automáticamente a ningún agente. Selecciónala al editar una promoción.</p><p class="form-error" role="alert"></p><div class="modal-actions"><button type="button" class="button secondary" data-action="close">Cancelar</button><button type="submit" class="button primary">Guardar tienda</button></div></form>`);
}
